import { useCallback, useState } from 'react';

import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { DataTable } from '@/components/tables/customTable/data-table';
import { columns } from './columns';
import { TraineeEvaluationsToolbar } from './trainee-evaluations-toolbar';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { FetchDataOptions } from '@/types/table.types';
import { TraineeEvaluation } from '../../types/configs.types';

interface Props {
    traineeId: number;
}

export default function TraineeEvaluationsTable({ traineeId }: Props) {
    const [data, setData] = useState<TraineeEvaluation[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            setIsLoading(true);
            try {
                const response = await apiGet({
                    endpoint: endpoints.review.list,
                    queryParams: {
                        page: options.pageIndex + 1,
                        pageSize: options.pageSize,
                        search: options.globalFilter,
                        ...options.filters,
                        employee_id: traineeId,
                    },
                });
                setData(response.data.data.data);
                const total = response.data.data.pagination.total;
                setTotalCount(total);
                setPageCount(Math.max(1, Math.ceil(total / options.pageSize)));
            } catch (error) {
                console.error('Error fetching evaluations:', error);
            } finally {
                setIsLoading(false);
            }
        },
        [traineeId],
    );

    return (
        <div className="rounded-xl border border-[#E8E7EA] bg-white overflow-hidden shadow-sm">
            <div className="bg-white-blue-100 px-4 py-3 border-b border-[#E8E7EA]">
                <UnderlineHeading text="سجل التقييمات" />
            </div>
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={TraineeEvaluationsToolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
