import { TraineesDetails } from '../../types/configs.types';
import { Card } from '@/types/statistics';
import { Star, ClipboardCheck, ListTodo, Clock } from 'lucide-react';
import defaultAvatar from '@/assets/imgs/user.png';
import { formatTraineeDate } from './traineeDetailsFormat';
import TraineeProfileCard from './TraineeProfileCard';
import TraineeKpiCards from './TraineeKpiCards';
import TraineeDetailInfoBlock from './TraineeDetailInfoBlock';
// import TraineeAttendanceCalendar from './TraineeAttendanceCalendar';
import TraineeEvaluationsTable from './TraineeEvaluationsTable';
// import CircularProgress from '@/components/circles/CircularProgress';

interface Props {
    trainee: TraineesDetails;
}

export default function TraineeInfo({ trainee }: Props) {
    const performance = Math.round(trainee.performance_rate ?? trainee.attendance_rate ?? 60);
    const imgSrc = trainee.personal_image?.startsWith('http')
        ? trainee.personal_image
        : trainee.personal_image || defaultAvatar;

    const roleLabel = trainee.program?.trim() ? `متدرب - ${trainee.program}` : 'متدرب - تطوير البرمجيات';

    const planPeriod =
        trainee.plan_period_label || (trainee.weeks_count ? `${trainee.weeks_count} أسبوع` : '6 أشهر / 24 أسبوع');

    const personalRows = [
        { label: 'رقم المتدرب', value: trainee.trainee_number || String(trainee.id) },
        { label: 'رقم الهوية', value: trainee.id_number || '—' },
        { label: 'تاريخ الميلاد', value: formatTraineeDate(trainee.birth_date) },
        { label: 'المؤهل', value: trainee.education_degree || '—' },
        { label: 'الجامعة', value: trainee.university || '—' },
        { label: 'سنة التخرج', value: trainee.graduation_year || '—' },
    ];

    const trainingRows = [
        { label: 'القسم', value: trainee.department || '—' },
        { label: 'البرنامج', value: trainee.program || '—' },
        { label: 'المشرف المباشر', value: trainee.direct_supervisor || '—' },
        { label: 'تاريخ البدء', value: formatTraineeDate(trainee.start_date) },
        { label: 'تاريخ الانتهاء', value: formatTraineeDate(trainee.end_date) },
        { label: 'مدة الخطة', value: planPeriod },
    ];

    const rating = trainee.overall_rating ?? 5;
    const attendanceKpi = Math.round(trainee.attendance_rate ?? 92);
    const tasks = trainee.completed_tasks ?? 22;
    const partTime = trainee.part_time_metric ?? 10;

    const kpiCards: Card[] = [
        {
            text: 'التقييم العام',
            num: `${rating}/5`,
            label: trainee.overall_rating_label,
            percent: 2,
            icon: <Star className="h-6 w-6 text-primery-blue-600" />,
        },
        {
            text: 'معدل الحضور',
            num: `${attendanceKpi}`,
            label: '%',
            percent: -0.3,
            negative: true,
            icon: <ClipboardCheck className="h-6 w-6 text-primery-blue-600" />,
        },
        {
            text: 'مهام مكتملة',
            num: tasks,
            percent: 1,
            icon: <ListTodo className="h-6 w-6 text-primery-blue-600" />,
        },
        {
            text: 'دوام جزئي',
            num: partTime,
            percent: 0,
            icon: <Clock className="h-6 w-6 text-primery-blue-600" />,
        },
    ];

    return (
        <div className="font-cairo space-y-8">
            <TraineeProfileCard
                name={trainee.name}
                traineeNumberDisplay={trainee.trainee_number || trainee.id}
                roleLabel={roleLabel}
                imageSrc={imgSrc}
                performancePercent={performance}
                performanceBadge={trainee.performance_label || 'مقبول'}
            />
            {/* <div className="flex relative flex-row justify-between px-4 bg-primery-blue-800 w-full text-white-blue-50 rounded-2xl items-center h-[242px]">
                <div className="absolute bottom-0">
                    <div className="flex flex-col items-center justify-center">
                        <div className="w-[242px] h-[242px] rounded-full overflow-hidden">
                            {trainee.personal_image ? (
                                <img
                                    src={trainee.personal_image}
                                    alt="Customer Image"
                                    className="w-full h-full object-cover"
                                />
                            ) : (
                                <div className="flex items-center justify-center h-full bg-gray-300">
                                    <p className="text-white-blue-50 text-8xl font-normal tracking-normal">
                                        {trainee.name
                                            .split(' ')
                                            .map((name) => name[0])
                                            .join('')}
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
                <div className="ms-[242px] ps-6 py-4">
                    <p className="text-start font-bold text-4xl leading-none tracking-normal py-3 mb-3">
                        {trainee.name}
                    </p>
                    <p className="text-start font-medium text-xl leading-none tracking-normal mt-2 mb-1">موظف</p>
                </div>
                <div className="my-[5.5px] flex flex-col justify-between items-center">
                    <p className="font-medium text-xs tracking-normal">التقييم</p>
                    <CircularProgress
                        textClassName="text-white-blue-50"
                        progressClassName="stroke-white-blue-50"
                        backgroundClassName="stroke-white-blue-700"
                        size={48}
                    />
                    <p className="font-medium text-xs tracking-normal border border-white-blue-50 p-1 rounded-sm">
                        مقبول
                    </p>
                </div>
            </div> */}

            <TraineeKpiCards cards={kpiCards} />

            <div className="flex flex-col lg:flex-row gap-6 items-stretch">
                <TraineeDetailInfoBlock title="البيانات الشخصية" rows={personalRows} />
                <TraineeDetailInfoBlock title="بيانات التدريب التفصيلية" rows={trainingRows} />
            </div>

            {/* <TraineeAttendanceCalendar /> */}

            <TraineeEvaluationsTable traineeId={trainee.id} />
        </div>
    );
}
