import UnderlineHeading from "@/components/heading/UnderlineHeading";

export type TraineeInfoRow = { label: string; value: string };

interface Props {
    title: string;
    rows: TraineeInfoRow[];
}

export default function TraineeDetailInfoBlock({ title, rows }: Props) {
    return (
        <div className="flex-1 min-w-[280px] rounded-xl border border-[#E8E7EA] bg-white overflow-hidden shadow-sm">
            <div className="bg-white-blue-100 px-4 py-3 border-b border-[#E8E7EA]">
                {/* <h3 className="text-base font-bold text-primery-blue-700 font-cairo text-start">{title}</h3> */}
                <UnderlineHeading text={title} />
            </div>
            <div className="divide-y divide-[#E8E7EA]">
                {rows.map((row) => (
                    <div key={row.label} className="flex flex-row items-stretch">
                        <div className=" shrink-0 bg-white-blue-50/80 px-3 py-3 text-sm font-semibold text-primery-blue-600 text-end border-s border-[#E8E7EA]">
                            {row.label}
                        </div>
                        <div className="flex-1 px-3 py-3 text-sm font-medium text-primery-blue-900 text-start">
                            {row.value}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
